        'Page loads without 500 error',
        `Loaded at ${initialUrl} (HTTP ${httpStatus})`,
        httpStatus === 200 || httpStatus === 'unknown' ? 'PASS' : 'FAIL'
      );
    }

    // ─── Step 2: Login if needed ────────────────────────────────────────────
    if (!isAssetsPage) {
      console.log('\n=== Step 2: Login ===');
      let loginSuccess = false;

      for (const password of PASSWORDS) {
        try {
          // Wait for email field
          await page.waitForSelector('input[type="email"], input[name="email"], input[placeholder*="mail"]', { timeout: 10000 });

          const emailField = await page.$('input[type="email"], input[name="email"], input[placeholder*="mail"]');
          const passwordField = await page.$('input[type="password"]');

          if (!emailField || !passwordField) {
            console.log('  Could not find login fields');
            break;
          }

          await emailField.fill(EMAIL);
          await passwordField.fill(password);

          await takeScreenshot(page, 'step2-login-form');

          const submitBtn = await page.$('button[type="submit"], button:has-text("Sign in"), button:has-text("Login"), button:has-text("Log in")');
          if (submitBtn) {
            await submitBtn.click();
          } else {
            await passwordField.press('Enter');
          }

          // Wait for navigation
          try {
            await page.waitForNavigation({ timeout: 15000, waitUntil: 'networkidle' });
          } catch (e) {
            // May not navigate if error
          }

          const afterLoginUrl = page.url();
          const stillOnLogin = afterLoginUrl.includes('/login') || afterLoginUrl.includes('/auth') || afterLoginUrl.includes('/signin');

          if (!stillOnLogin) {
            loginSuccess = true;
            logStep(
              `Login with password: ${password.substring(0, 4)}***`,
              'Successful login and redirect',
              `Successfully logged in, redirected to ${afterLoginUrl}`,
              'PASS'
            );
            break;
          } else {
            // Check for error message
            const errorText = await page.textContent('body');
            const hasError = errorText.includes('Invalid') || errorText.includes('incorrect') || errorText.includes('wrong');
            if (hasError) {
              console.log(`  Password ${password} failed, trying next...`);
              // Clear fields for retry
              await emailField.fill('');
              await passwordField.fill('');
            }
          }
        } catch (e) {
          console.log(`  Login attempt with ${password} error: ${e.message}`);
        }
      }

      if (!loginSuccess) {
        logStep(
          'Login attempt',
          'Successful login',
          'Login failed with all passwords',
          'FAIL'
        );
        await takeScreenshot(page, 'step2-login-failed');
      } else {
        await takeScreenshot(page, 'step2-login-success');
      }
    } else {
      logStep('Login check', 'Login may be needed', 'Already on assets page, no login needed', 'PASS');
    }

    // ─── Step 3: Navigate to assets page after login ─────────────────────
    console.log('\n=== Step 3: Navigate to /assets after login ===');
    const currentUrl = page.url();
    if (!currentUrl.includes('/assets')) {
      await page.goto(`${BASE_URL}/assets`, { waitUntil: 'domcontentloaded', timeout: 30000 });
    }

    await page.waitForTimeout(2000); // Extra wait for React hydration
    const assetsUrl = page.url();
    await takeScreenshot(page, 'step3-assets-page');

    const onAssetsPage = assetsUrl.includes('/assets');
    logStep(
      'Navigate to /assets page',
      'URL contains /assets',
      `Current URL: ${assetsUrl}`,
      onAssetsPage ? 'PASS' : 'FAIL'
    );

    // ─── Step 4: Check for NextRouter error in console ────────────────────
    console.log('\n=== Step 4: Check console for NextRouter errors ===');

    // Also reload to get fresh console output
    consoleErrors.length = 0;
    consoleMessages.length = 0;

    await page.reload({ waitUntil: 'domcontentloaded', timeout: 30000 });
    await page.waitForTimeout(3000);

    await takeScreenshot(page, 'step4-after-reload');

    const nextRouterErrors = consoleErrors.filter(m =>
      m.text.includes('NextRouter was not mounted') ||
      m.text.includes('NextRouter') ||
      m.text.includes('next/router') ||
      m.text.includes('useRouter')
    );

    const allErrors = consoleErrors.filter(m =>
      !m.text.includes('favicon') &&
      !m.text.includes('analytics') &&
      !m.text.includes('gtag')
    );

    if (nextRouterErrors.length === 0) {
      logStep(
        'Check console for "NextRouter was not mounted" error',
        'No NextRouter errors in console',
        `No NextRouter errors found. Total console errors: ${allErrors.length}`,
        'PASS'
      );
    } else {
      logStep(
        'Check console for "NextRouter was not mounted" error',
        'No NextRouter errors in console',
        `FOUND NextRouter errors: ${nextRouterErrors.map(e => e.text).join('; ')}`,
        'FAIL'
      );
    }

    // Print all console errors for diagnostic
    if (allErrors.length > 0) {
      console.log('\n  Console errors found:');
      allErrors.forEach(e => console.log(`    [${e.type}] ${e.text.substring(0, 200)}`));
    }

    // ─── Step 5: Verify Asset Dashboard content ───────────────────────────
    console.log('\n=== Step 5: Verify Asset Dashboard content ===');
    const pageContent = await page.textContent('body');
    const pageTitle = await page.title();

    const hasAssetManagement =
      pageContent.includes('Asset') ||
      pageContent.includes('asset') ||
      pageTitle.includes('Asset');

    const hasStats =
      pageContent.includes('Total') ||
      pageContent.includes('Available') ||
      pageContent.includes('Assigned') ||
      pageContent.includes('Maintenance') ||
      pageContent.includes('Dashboard');

    await takeScreenshot(page, 'step5-dashboard-content');

    // Get page heading
    const heading = await page.$eval('h1, h2, [role="heading"]', el => el.textContent).catch(() => 'no heading found');

    logStep(
      'Verify Asset Dashboard content visible',
      'Asset Dashboard with stats visible',
      `Page title: "${pageTitle}", Heading: "${heading}", Has asset content: ${hasAssetManagement}, Has stats: ${hasStats}`,
      hasAssetManagement ? 'PASS' : 'FAIL'
    );

    // ─── Step 6: Check HTTP status ────────────────────────────────────────
    console.log('\n=== Step 6: Verify HTTP 200 ===');
    const finalResponse = await page.goto(`${BASE_URL}/assets`, { waitUntil: 'domcontentloaded', timeout: 30000 });
    const finalStatus = finalResponse ? finalResponse.status() : 'unknown';
    await takeScreenshot(page, 'step6-final');

    logStep(
      'HTTP status check for /assets',
      'HTTP 200',
      `HTTP ${finalStatus}`,
      finalStatus === 200 ? 'PASS' : 'FAIL'
    );

    // ─── Full page screenshot ─────────────────────────────────────────────
    await page.screenshot({ path: path.join(SCREENSHOTS_DIR, 'assets-full-page.png'), fullPage: true });
    console.log(`\n  Full-page screenshot: /tmp/qa-screenshots/assets-full-page.png`);

  } catch (err) {
    console.error('\nFATAL ERROR:', err.message);
    await takeScreenshot(page, 'fatal-error').catch(() => {});
    results.push({ step: stepNum + 1, description: 'Unexpected error', expected: 'No errors', actual: err.message, status: 'FAIL' });
  } finally {
    await browser.close();
  }

  // ─── Print Report ──────────────────────────────────────────────────────
  console.log('\n\n============================================');
  console.log('  BROWSER QA REPORT');
  console.log('============================================');
  console.log(`Story: Assets Page Load Validation`);
  console.log(`URL: ${BASE_URL}/assets`);
  console.log(`Date: ${new Date().toISOString()}`);
  console.log(`Environment: Staging`);
  console.log('--------------------------------------------');

  results.forEach(r => {
    console.log(`\nStep ${r.step}: ${r.description}`);
    console.log(`  Expected: ${r.expected}`);
    console.log(`  Actual:   ${r.actual}`);
    console.log(`  Result:   ${r.status}`);
  });

  const passed = results.filter(r => r.status === 'PASS').length;
  const failed = results.filter(r => r.status === 'FAIL').length;
  const warnings = results.filter(r => r.status === 'WARNING').length;
  const overall = failed > 0 ? 'FAIL' : 'PASS';

  console.log('\n--------------------------------------------');
  console.log('SUMMARY');
  console.log(`  Total Steps: ${results.length}`);
  console.log(`  Passed:      ${passed}`);
  console.log(`  Failed:      ${failed}`);
  console.log(`  Warnings:    ${warnings}`);
  console.log(`  Result:      ${overall}`);
  console.log('============================================\n');

  process.exit(failed > 0 ? 1 : 0);
}

run().catch(err => {
  console.error('Script error:', err);
  process.exit(1);
});

