const { chromium } = require('/home/hein/Workspace/FF_Next.js/node_modules/playwright');
const path = require('path');

const SCREENSHOTS_DIR = '/tmp/qa-screenshots';
const BASE_URL = 'https://vf.fibreflow.app';
const EMAIL = 'hein@velocityfibre.co.za';
const PASSWORDS = ['Temp1234!', 'Velo2026!'];

const results = [];
let stepNum = 0;

function logStep(description, expected, actual, status) {
  stepNum++;
  const entry = { step: stepNum, description, expected, actual, status };
  results.push(entry);
  console.log(`\nStep ${stepNum}: ${description}`);
  console.log(`  Expected: ${expected}`);
  console.log(`  Actual:   ${actual}`);
  console.log(`  Result:   ${status}`);
  return entry;
}

async function takeScreenshot(page, name) {
  const filePath = path.join(SCREENSHOTS_DIR, `assets-${name}.png`);
  await page.screenshot({ path: filePath, fullPage: false });
  console.log(`  Screenshot: ${filePath}`);
  return filePath;
}

async function login(page) {
  // The sign-in page is a two-step form:
  // Step 1: Enter email, click "Continue"
  // Step 2: Enter password, click "Sign In"

  await page.waitForSelector('#username, input[type="email"]', { timeout: 10000 });

  // Fill email
  const emailInput = await page.$('#username, input[type="email"]');
  if (!emailInput) {
    console.log('  No email field found');
    return false;
  }
  await emailInput.fill(EMAIL);
  console.log(`  Filled email: ${EMAIL}`);

  await takeScreenshot(page, 'login-step1-email');

  // Click Continue button
  const continueBtn = await page.$('button[type="submit"]');
  if (continueBtn) {
    await continueBtn.click();
    console.log('  Clicked Continue button');
  } else {
    await emailInput.press('Enter');
  }

  // Wait for password field to appear
  await page.waitForTimeout(2000);
  await takeScreenshot(page, 'login-step1-after-continue');

  // Check if password field appeared
  const passwordField = await page.$('input[type="password"]');
  if (!passwordField) {
    // Maybe it was a single-step form and we're now somewhere else
    const currentUrl = page.url();
    console.log(`  No password field after Continue. Current URL: ${currentUrl}`);
    if (!currentUrl.includes('/sign-in')) {
      // Successfully authenticated
      return true;
    }
    return false;
  }

  // Try each password
  for (const password of PASSWORDS) {
    const pwField = await page.$('input[type="password"]');
    if (!pwField) break;

    await pwField.fill(password);
    console.log(`  Trying password: ${password.substring(0, 4)}***`);

    await takeScreenshot(page, `login-step2-password-${password.substring(0, 4)}`);

    const signInBtn = await page.$('button[type="submit"]');
    if (signInBtn) {
      await signInBtn.click();
    } else {
      await pwField.press('Enter');
    }

    try {
      await page.waitForNavigation({ timeout: 10000, waitUntil: 'domcontentloaded' });
    } catch (e) {
      // May timeout if no navigation
    }

    await page.waitForTimeout(2000);
    const afterUrl = page.url();
    const stillOnSignIn = afterUrl.includes('/sign-in');

    if (!stillOnSignIn) {
      console.log(`  Login successful! Redirected to: ${afterUrl}`);
      return true;
    } else {
      console.log(`  Password ${password} failed. Still on sign-in page.`);
      // Clear password field and try again
      const pwFieldRetry = await page.$('input[type="password"]');
      if (pwFieldRetry) {
        await pwFieldRetry.fill('');
      }
    }
  }

  return false;
}

async function run() {
  const browser = await chromium.launch({
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });

  const context = await browser.newContext({
    viewport: { width: 1280, height: 900 }
  });

  // Capture console messages
  const consoleErrors = [];
  const allConsoleMessages = [];

  const page = await context.newPage();

  page.on('console', msg => {
    const text = msg.text();
    allConsoleMessages.push({ type: msg.type(), text });
    if (msg.type() === 'error') {
      consoleErrors.push({ type: 'error', text });
    }
  });

  page.on('pageerror', err => {
    consoleErrors.push({ type: 'pageerror', text: err.message });
    allConsoleMessages.push({ type: 'pageerror', text: err.message });
  });

  try {
    // ─── Step 1: Navigate to /assets ──────────────────────────────────────
    console.log('\n=== Step 1: Navigate to https://vf.fibreflow.app/assets ===');
    const response = await page.goto(`${BASE_URL}/assets`, {
      waitUntil: 'domcontentloaded',
      timeout: 30000
    });
    await page.waitForTimeout(2000);

    const initialUrl = page.url();
    const httpStatus = response ? response.status() : 'unknown';

    await takeScreenshot(page, 'step1-initial');

    const isSignIn = initialUrl.includes('/sign-in');
    const isAssets = initialUrl.includes('/assets');

    logStep(
      'Navigate to /assets',
      'Page loads (HTTP 200, redirect to sign-in or direct access)',
      `URL: ${initialUrl}, HTTP: ${httpStatus}`,
      (httpStatus === 200 && (isSignIn || isAssets)) ? 'PASS' : 'FAIL'
    );

    // ─── Step 2: Login ─────────────────────────────────────────────────────
    console.log('\n=== Step 2: Login ===');

    let loginSuccess = false;

    if (isAssets) {
      logStep('Login check', 'Login may be needed', 'Already on assets page — no login needed', 'PASS');
      loginSuccess = true;
    } else {
      loginSuccess = await login(page);

      if (loginSuccess) {
        logStep(
          'Login with credentials',
          'Successful login and redirect away from sign-in',
          `Logged in. Current URL: ${page.url()}`,
          'PASS'
        );
        await takeScreenshot(page, 'step2-login-success');
      } else {
        logStep(
          'Login with credentials',
          'Successful login',
          `Login failed. Still at: ${page.url()}`,
          'FAIL'
        );
        await takeScreenshot(page, 'step2-login-failed');
      }
    }

    // ─── Step 3: Navigate to /assets after login ──────────────────────────
    console.log('\n=== Step 3: Navigate to /assets after login ===');
    const currentUrl = page.url();

    if (!currentUrl.includes('/assets')) {
      await page.goto(`${BASE_URL}/assets`, {
        waitUntil: 'domcontentloaded',
        timeout: 30000
      });
      await page.waitForTimeout(3000);
    }

    const assetsUrl = page.url();
    await takeScreenshot(page, 'step3-assets-page');

    const onAssetsPage = assetsUrl.includes('/assets');
    logStep(
      'Land on /assets page after login',
      'URL contains /assets',
      `Current URL: ${assetsUrl}`,
      onAssetsPage ? 'PASS' : 'FAIL'
    );

    // ─── Step 4: Check console for NextRouter errors ───────────────────────
    console.log('\n=== Step 4: Check for NextRouter errors ===');

    // Clear and reload for fresh console
    consoleErrors.length = 0;
    allConsoleMessages.length = 0;

    await page.reload({ waitUntil: 'domcontentloaded', timeout: 30000 });
    await page.waitForTimeout(4000); // Wait for React to hydrate

    await takeScreenshot(page, 'step4-after-reload');

    const nextRouterErrors = [...consoleErrors, ...allConsoleMessages].filter(m =>
      m.text.includes('NextRouter was not mounted') ||
      m.text.includes('NextRouter') ||
      (m.text.includes('next/router') && m.text.includes('Error'))
    );

    const significantErrors = consoleErrors.filter(m =>
      !m.text.includes('favicon') &&
      !m.text.includes('analytics') &&
      !m.text.includes('gtag') &&
      !m.text.includes('401') // 401s are expected for unauthenticated resources
    );

    console.log(`\n  All console messages (${allConsoleMessages.length} total):`);
    allConsoleMessages.forEach(m => {
      if (m.type === 'error' || m.type === 'pageerror' || m.text.includes('NextRouter') || m.text.includes('Error')) {
        console.log(`    [${m.type}] ${m.text.substring(0, 300)}`);
      }
    });

    if (nextRouterErrors.length === 0) {
      logStep(
        'Check console for "NextRouter was not mounted" error',
        'No NextRouter errors in console',
        `No NextRouter errors found. Total console errors: ${consoleErrors.length}, significant: ${significantErrors.length}`,
        'PASS'
      );
    } else {
      logStep(
        'Check console for "NextRouter was not mounted" error',
        'No NextRouter errors in console',
        `FOUND NextRouter errors: ${nextRouterErrors.map(e => e.text).join('; ')}`,
        'FAIL'
      );
    }

    // Also print significant errors
    if (significantErrors.length > 0) {
      console.log('\n  Significant console errors:');
      significantErrors.forEach(e => console.log(`    [${e.type}] ${e.text.substring(0, 200)}`));
    }

    // ─── Step 5: Verify Asset Dashboard content ────────────────────────────
    console.log('\n=== Step 5: Verify Asset Dashboard content ===');
    const pageTitle = await page.title();
    const pageContent = await page.textContent('body');

    const hasAssetContent =
      pageContent.includes('Asset') ||
      pageContent.includes('asset') ||
      pageTitle.toLowerCase().includes('asset');

    const hasStats =
      pageContent.includes('Total Assets') ||
      pageContent.includes('Available') ||
      pageContent.includes('Assigned') ||
      (pageContent.includes('Total') && pageContent.includes('Asset')) ||
      pageContent.includes('Maintenance') ||
      pageContent.includes('Dashboard');

    const hasTabs =
      pageContent.includes('Overview') ||
      pageContent.includes('Inventory') ||
      pageContent.includes('Assign') ||
      pageContent.includes('History');

    // Get heading
    const heading = await page.$eval('h1, h2, [role="heading"]', el => el.textContent.trim()).catch(() => 'not found');

    await takeScreenshot(page, 'step5-dashboard-content');

    // Take full page screenshot
    await page.screenshot({
      path: path.join(SCREENSHOTS_DIR, 'assets-full-page.png'),
      fullPage: true
    });

    logStep(
      'Verify Asset Dashboard content visible',
      'Asset Dashboard with stats/navigation visible',
      `Title: "${pageTitle}", Heading: "${heading}", Has asset content: ${hasAssetContent}, Has stats: ${hasStats}, Has tabs: ${hasTabs}`,
      hasAssetContent ? 'PASS' : 'FAIL'
    );

    // ─── Step 6: HTTP 200 verification ────────────────────────────────────
    console.log('\n=== Step 6: HTTP 200 check ===');
    const httpCheck = await page.evaluate(async () => {
      try {
        const resp = await fetch(window.location.href, { method: 'GET' });
        return resp.status;
      } catch (e) {
        return 'fetch-error';
      }
    });

    await takeScreenshot(page, 'step6-final');

    logStep(
      'HTTP status for /assets',
      'HTTP 200',
      `HTTP ${httpCheck}`,
      httpCheck === 200 ? 'PASS' : 'WARNING'
    );

  } catch (err) {
    console.error('\nFATAL ERROR:', err.message);
    await takeScreenshot(page, 'fatal-error').catch(() => {});
    results.push({
      step: stepNum + 1,
      description: 'Script execution error',
      expected: 'No errors',
      actual: err.message,
      status: 'FAIL'
    });
  } finally {
    await browser.close();
  }

  // ─── Final Report ──────────────────────────────────────────────────────
  console.log('\n\n============================================');
  console.log('  BROWSER QA REPORT');
  console.log('============================================');
  console.log('Story: Assets Page Load Validation');
  console.log(`URL: ${BASE_URL}/assets`);
  console.log(`Date: ${new Date().toISOString()}`);
  console.log('Environment: Staging (vf.fibreflow.app)');
  console.log('--------------------------------------------');

  results.forEach(r => {
    console.log(`\nStep ${r.step}: ${r.description}`);
    console.log(`  Expected: ${r.expected}`);
    console.log(`  Actual:   ${r.actual}`);
    console.log(`  Result:   ${r.status}`);
  });

  const passed = results.filter(r => r.status === 'PASS').length;
  const failed = results.filter(r => r.status === 'FAIL').length;
  const warnings = results.filter(r => r.status === 'WARNING').length;
  const overall = failed > 0 ? 'FAIL' : 'PASS';

  console.log('\n--------------------------------------------');
  console.log('SUMMARY');
  console.log(`  Total Steps: ${results.length}`);
  console.log(`  Passed:      ${passed}`);
  console.log(`  Failed:      ${failed}`);
  console.log(`  Warnings:    ${warnings}`);
  console.log(`  Overall:     ${overall}`);
  console.log('============================================\n');

  console.log('Screenshots saved to /tmp/qa-screenshots/assets-*.png');

  process.exit(failed > 0 ? 1 : 0);
}

run().catch(err => {
  console.error('Script error:', err);
  process.exit(1);
});

