() => {
  // Capture everything we need for Steps 2-5 analysis
  const main = document.querySelector('main');
  const heading = main?.querySelector('h1')?.textContent;
  const subtitle = main?.querySelector('p, [class*="subtitle"]')?.textContent;

  // Find any project-related selects/dropdowns
  const selects = Array.from(document.querySelectorAll('select')).map(s => ({
    id: s.id, name: s.name, options: Array.from(s.options).map(o => o.text)
  }));
  const comboboxes = Array.from(document.querySelectorAll('[role="combobox"]')).map(c => ({
    id: c.id, text: c.textContent?.trim()?.slice(0, 50)
  }));
  const listboxes = Array.from(document.querySelectorAll('[role="listbox"]')).map(l => ({
    text: l.textContent?.trim()?.slice(0, 50)
  }));

  // Stat cards
  const statHeadings = Array.from(main?.querySelectorAll('h3') || []).map(h => h.textContent?.trim());

  // Error banners
  const errors = Array.from(document.querySelectorAll('[class*="error"], [role="alert"], [class*="Error"]'))
    .map(e => e.textContent?.trim()?.slice(0, 100))
    .filter(t => t);

  // All buttons in main
  const mainButtons = Array.from(main?.querySelectorAll('button') || []).map(b => b.textContent?.trim()?.slice(0, 50));

  // Table rows
  const tableRows = Array.from(main?.querySelectorAll('tr, [role="row"]') || []).map(r => r.textContent?.trim()?.slice(0, 80));

  // No data message
  const noDataMsg = Array.from(main?.querySelectorAll('*') || []).find(el => el.textContent?.includes('No data available'))?.textContent?.trim();

  return {
    heading, subtitle, selects, comboboxes, listboxes,
    statHeadings, errors, mainButtons, tableRows: tableRows.slice(0, 10), noDataMsg
  };
}

