'use client';

/**
 * Staff List Component - Refactored Version
 * Main container for staff management with split components
 */

import React, { useState } from 'react';
import { useRouter } from 'next/navigation';
import { useQuery } from '@tanstack/react-query';
import { staffService } from '@/services/staffService';
import { StaffImport } from '@/components/staff/StaffImport';
import { StaffListHeader } from './StaffListHeader';
import { StaffFilters } from './StaffFilters';
import { StaffTable } from './StaffTable';
import { StaffFilter, StaffMember, StaffSummary } from '@/types/staff.types';
import { log } from '@/lib/logger';
import { formatLabel } from '@/lib/utils';

export function StaffList() {
  const router = useRouter();
  const [searchTerm, setSearchTerm] = useState('');
  const [showImport, setShowImport] = useState(false);
  const [filter, setFilter] = useState<StaffFilter>({});
  const [showFilters, setShowFilters] = useState(false);

  const { data: staff = [], isLoading, error, refetch } = useQuery({
    queryKey: ['staff', filter],
    queryFn: async () => {
      const result = await staffService.getAll(filter);
      return result as StaffMember[];
    }
  });

  const { data: summary } = useQuery({
    queryKey: ['staff-summary'],
    queryFn: async () => {
      const result = await staffService.getStaffSummary();
      return result as StaffSummary;
    }
  });

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    setFilter(prev => ({ ...prev, searchTerm }));
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Are you sure you want to delete this staff member?')) {
      return;
    }

    try {
      await staffService.delete(id);
      await refetch();
    } catch (error) {
      log.error('Failed to delete staff member:', { data: error }, 'StaffList');
    }
  };

  const handleExport = async () => {
    try {
      const csvContent = staff.map(member => ({
        'Employee ID': member.employeeId,
        'Name': member.name,
        'Email': member.email,
        'Phone': member.phone,
        'Position': member.position || '',
        'Department': formatLabel(member.department, ''),
        'Status': member.status || '',
        'Start Date': member.startDate || '',
        'Project Count': member.currentProjectCount || 0
      }));

      if (csvContent.length === 0) {
        throw new Error('No staff data to export');
      }

      const firstRow = csvContent[0];
      if (!firstRow) {
        throw new Error('Invalid staff data');
      }

      const csv = [
        Object.keys(firstRow).join(','),
        ...csvContent.map(row => Object.values(row).join(','))
      ].join('\n');

      const blob = new Blob([csv], { type: 'text/csv' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      // Build descriptive filename with active filters
      const filterParts: string[] = [];
      if (filter.status) filterParts.push(filter.status);
      if (filter.department) filterParts.push(filter.department.replace(/\s+/g, '-'));
      if (filter.position) filterParts.push(filter.position.replace(/\s+/g, '-'));
      if (filter.searchTerm) filterParts.push('search');
      const filterSuffix = filterParts.length > 0 ? `-${filterParts.join('-')}` : '-all';
      a.download = `staff${filterSuffix}-${new Date().toISOString().split('T')[0]}.csv`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    } catch (error) {
      log.error('Export failed:', { data: error }, 'StaffList');
    }
  };

  if (showImport) {
    return (
      <div>
        <div className="mb-4 flex items-center justify-between">
          <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Import Staff</h1>
          <button
            onClick={() => setShowImport(false)}
            className="px-4 py-2 bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-primary)] border border-[var(--ff-border-light)] rounded-md hover:bg-[var(--ff-bg-hover)]"
          >
            Back to List
          </button>
        </div>
        <StaffImport onComplete={async () => {
          setShowImport(false);
          await refetch();
        }} />
      </div>
    );
  }

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="text-center py-12">
        <p className="text-red-600">Failed to load staff data</p>
        <button 
          onClick={() => refetch()}
          className="mt-2 px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700"
        >
          Retry
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <StaffListHeader
        totalStaff={summary?.totalStaff || 0}
        activeStaff={summary?.activeStaff || 0}
        utilizationRate={Math.round(summary?.utilizationRate || 0)}
        showFilters={showFilters}
        setShowFilters={setShowFilters}
        onAddStaff={() => router.push('/staff/new')}
        onImport={() => setShowImport(true)}
        onSettings={() => router.push('/staff/settings')}
        onExport={handleExport}
        filter={filter}
      />

      {showFilters && (
        <StaffFilters
          searchTerm={searchTerm}
          setSearchTerm={setSearchTerm}
          filter={filter}
          setFilter={setFilter}
          onSearch={handleSearch}
        />
      )}

      <StaffTable
        staff={staff}
        onView={(staff: StaffMember) => router.push(`/staff/${staff.id}`)}
        onEdit={(staff: StaffMember) => router.push(`/staff/${staff.id}/edit`)}
        onDelete={handleDelete}
      />

      {staff.length === 0 && (
        <div className="text-center py-12">
          <p className="text-[var(--ff-text-secondary)] text-lg">No staff members found</p>
          <button
            onClick={() => router.push('/staff/new')}
            className="mt-4 px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700"
          >
            Add First Staff Member
          </button>
        </div>
      )}
    </div>
  );
}

import { useState, useCallback, useEffect } from 'react';
import { useDebounce } from './useDebounce';
import { log } from '@/lib/logger';

interface SearchResult {
  type: 'project' | 'staff' | 'client' | 'contractor';
  id: string;
  title: string;
  description: string;
  relevance: number;
}

interface SearchResponse {
  success: boolean;
  query: string;
  results: SearchResult[];
  suggestions: string[];
  popular: string[];
  total: number;
}

export function useGlobalSearch(initialQuery = '') {
  const [query, setQuery] = useState(initialQuery);
  const [results, setResults] = useState<SearchResult[]>([]);
  const [suggestions, setSuggestions] = useState<string[]>([]);
  const [popularSearches, setPopularSearches] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Debounce search query to avoid too many API calls
  const debouncedQuery = useDebounce(query, 300);

  const search = useCallback(async (searchQuery: string) => {
    if (!searchQuery || searchQuery.trim().length < 2) {
      setResults([]);
      setSuggestions([]);
      return;
    }

    setLoading(true);
    setError(null);

    try {
      const response = await fetch(`/api/search?q=${encodeURIComponent(searchQuery)}`);

      if (!response.ok) {
        throw new Error('Search failed');
      }

      const data: SearchResponse = await response.json();

      if (data.success) {
        setResults(data.results);
        setSuggestions(data.suggestions);
        setPopularSearches(data.popular);
      } else {
        throw new Error(data.error || 'Search failed');
      }
    } catch (err) {
      log.error('Search error', err, 'useGlobalSearch');
      setError(err instanceof Error ? err.message : 'Search failed');
      setResults([]);
    } finally {
      setLoading(false);
    }
  }, []);

  // Auto-search when debounced query changes
  useEffect(() => {
    if (debouncedQuery) {
      search(debouncedQuery);
    } else {
      setResults([]);
      setSuggestions([]);
    }
  }, [debouncedQuery, search]);

  // Get popular searches on mount
  useEffect(() => {
    fetch('/api/search?q=&popular=true')
      .then(res => res.json())
      .then(data => {
        if (data.popular) {
          setPopularSearches(data.popular);
        }
      })
      .catch(err => log.error('Failed to load popular searches', err, 'useGlobalSearch'));
  }, []);

  const clearSearch = useCallback(() => {
    setQuery('');
    setResults([]);
    setSuggestions([]);
    setError(null);
  }, []);

  return {
    query,
    setQuery,
    results,
    suggestions,
    popularSearches,
    loading,
    error,
    search,
    clearSearch
  };
}

// Debounce hook (if not already exists)
export function useDebounce<T>(value: T, delay: number): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedValue(value);
    }, delay);

    return () => {
      clearTimeout(handler);
    };
  }, [value, delay]);

  return debouncedValue;
}

/**
 * Staff Filters Component
 */

import { Search } from 'lucide-react';
import type { StaffFilter, Department, StaffStatus, StaffLevel } from '@/types/staff.types';
import { formatLabel } from '@/lib/utils';

interface StaffFiltersProps {
  searchTerm: string;
  setSearchTerm: (term: string) => void;
  filter: StaffFilter;
  setFilter: (filter: StaffFilter) => void;
  onSearch: (e: React.FormEvent) => void;
}

const departments = ['Engineering', 'Operations', 'Quality Assurance', 'Administration'];
const statuses = ['active', 'inactive', 'on_leave'];
const levels = ['junior', 'mid', 'senior', 'lead', 'manager'];

export function StaffFilters({
  searchTerm,
  setSearchTerm,
  filter,
  setFilter,
  onSearch
}: StaffFiltersProps) {
  return (
    <div className="bg-[var(--ff-bg-secondary)] p-4 border-b border-[var(--ff-border-light)]">
      <form onSubmit={onSearch} className="space-y-4">
        <div className="grid grid-cols-1 md:grid-cols-5 gap-4">
          {/* Search */}
          <div className="md:col-span-2 relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-[var(--ff-text-secondary)]" />
            <input
              type="text"
              placeholder="Search staff..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="pl-10 pr-4 py-2 w-full bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-primary)] border border-[var(--ff-border-light)] rounded-md focus:ring-blue-500 focus:border-blue-500 placeholder:text-[var(--ff-text-secondary)]"
            />
          </div>

          {/* Department Filter */}
          <select
            value={filter.department?.[0] || ''}
            onChange={(e) => setFilter({ ...filter, department: e.target.value ? [e.target.value as Department] : [] })}
            className="px-3 py-2 bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-primary)] border border-[var(--ff-border-light)] rounded-md focus:ring-blue-500 focus:border-blue-500"
          >
            <option value="">All Departments</option>
            {departments.map(dept => (
              <option key={dept} value={dept}>{dept}</option>
            ))}
          </select>

          {/* Status Filter */}
          <select
            value={filter.status?.[0] || ''}
            onChange={(e) => setFilter({ ...filter, status: e.target.value ? [e.target.value as StaffStatus] : [] })}
            className="px-3 py-2 bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-primary)] border border-[var(--ff-border-light)] rounded-md focus:ring-blue-500 focus:border-blue-500"
          >
            <option value="">All Statuses</option>
            {statuses.map(status => (
              <option key={status} value={status}>
                {formatLabel(status)}
              </option>
            ))}
          </select>

          {/* Level Filter */}
          <select
            value={filter.level?.[0] || ''}
            onChange={(e) => setFilter({ ...filter, level: e.target.value ? [e.target.value as StaffLevel] : [] })}
            className="px-3 py-2 bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-primary)] border border-[var(--ff-border-light)] rounded-md focus:ring-blue-500 focus:border-blue-500"
          >
            <option value="">All Levels</option>
            {levels.map(level => (
              <option key={level} value={level}>
                {level.charAt(0).toUpperCase() + level.slice(1)}
              </option>
            ))}
          </select>
        </div>

        <div className="flex justify-between items-center">
          <button
            type="submit"
            className="px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500"
          >
            Apply Filters
          </button>

          <button
            type="button"
            onClick={() => {
              setSearchTerm('');
              setFilter({});
            }}
            className="text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]"
          >
            Clear all filters
          </button>
        </div>
      </form>
    </div>
  );
}

// Main page component that renders the Staff List
import { StaffList } from './components/StaffList';

export function StaffPage() {
  return <StaffList />;
}

