() => {
  // Check for error banners/alerts
  const errorSelectors = [
    '[role="alert"]',
    '.error',
    '.error-banner',
    '[class*="error"]',
    '[class*="alert-danger"]',
    '[class*="alert-error"]'
  ];
  const results = [];
  for (const sel of errorSelectors) {
    const els = document.querySelectorAll(sel);
    for (const el of els) {
      const text = el.textContent.trim();
      if (text && !el.getAttribute('aria-live')) {
        results.push({ selector: sel, text: text.substring(0, 100) });
      }
    }
  }
  return results;
}

