() => {
  // Find the PR26-00001 element and its clickable parent
  const allElements = document.querySelectorAll('*');
  const prEl = Array.from(allElements).find(el => el.textContent === 'PR26-00001');
  if (prEl) {
    let parent = prEl;
    for (let i = 0; i < 5; i++) {
      parent = parent.parentElement;
      if (!parent) break;
      const style = window.getComputedStyle(parent);
      const cursor = style.cursor;
      if (cursor === 'pointer') return { found: true, cursor, tag: parent.tagName, class: parent.className.substring(0, 100) };
    }
    return { found: true, cursor: 'none clickable', tag: prEl.tagName, text: prEl.textContent };
  }
  return { found: false };
}

