() => {
  // Install navigation interceptor
  const origPush = history.pushState;
  const origReplace = history.replaceState;
  window._navLog = [];

  history.pushState = function(...args) {
    window._navLog.push({type: 'pushState', args: args.map(String), stack: new Error().stack});
    return origPush.apply(this, args);
  };
  history.replaceState = function(...args) {
    window._navLog.push({type: 'replaceState', args: args.map(String), stack: new Error().stack});
    return origReplace.apply(this, args);
  };

  window.addEventListener('popstate', (e) => {
    window._navLog.push({type: 'popstate', state: String(e.state)});
  });

  return 'Navigation interceptor installed. Current URL: ' + window.location.href;
}

