  // Wait for button to exist and click immediately
  const maxWait = 5000;
  const start = Date.now();
  while (Date.now() - start < maxWait) {
    const buttons = document.querySelectorAll('button');
    let addStaffBtn = null;
    buttons.forEach(btn => {
      if (btn.textContent.trim() === 'Add Staff') addStaffBtn = btn;
    });
