tool_input.function:
() => {
  // Stop all navigation by overriding pushState and replaceState
  const origPush = history.pushState.bind(history);
  const origReplace = history.replaceState.bind(history);

  // Record navigation attempts
  const navAttempts = [];

  history.pushState = function(...args) {
    navAttempts.push({type: 'push', url: args[2], stack: new Error().stack.split('\n').slice(1, 4).join(' | ')});
    return origPush(...args);
  };

  history.replaceState = function(...args) {
    navAttempts.push({type: 'replace', url: args[2], stack: new Error().stack.split('\n').slice(1, 4).join(' | ')});
    return origReplace(...args);
  };

  window.__navAttempts = navAttempts;
  return 'monitoring active, current url: ' + window.location.href;
}

