() => {
  const url = window.location.href;
  const allInputs = Array.from(document.querySelectorAll('input'));
  const staffSearch = allInputs.find(el => el.placeholder && el.placeholder.includes('Search by name'));

  if (!staffSearch) return { error: 'not found', url };

  staffSearch.focus();

  // Get React fiber to trigger the onChange handler directly
  const fiber = staffSearch._reactFiber || staffSearch.__reactFiber || staffSearch[Object.keys(staffSearch).find(k => k.startsWith('__reactFiber'))];

  if (fiber) {
    // Try to find and call the onChange prop directly from the fiber
    let node = fiber;
    let attempts = 0;
    while (node && attempts < 10) {
      if (node.pendingProps && node.pendingProps.onChange) {
        const syntheticEvent = { target: staffSearch, currentTarget: staffSearch, nativeEvent: new Event('change'), bubbles: true };
        staffSearch.value = 'VF';
        node.pendingProps.onChange(syntheticEvent);
        return { url: window.location.href, method: 'fiber-onChange', value: staffSearch.value };
      }
      if (node.memoizedProps && node.memoizedProps.onChange) {
        const syntheticEvent = { target: staffSearch, currentTarget: staffSearch, nativeEvent: new Event('change'), bubbles: true };
        staffSearch.value = 'VF';
        node.memoizedProps.onChange(syntheticEvent);
        return { url: window.location.href, method: 'fiber-memoized', value: staffSearch.value };
      }
      node = node.return;
      attempts++;
    }
    return { url: window.location.href, fiberFound: true, noOnChange: true };
  }

  return { url: window.location.href, fiberFound: false };
}

